# D1 (contract 68): the fourth Origin Fragment glints under the bench of the square (the old line first, then the rumor + the clue).
@script rumor_ambar npc
    npc_face_hero npc_a
    say ambar.npc.a
    say d1.ambar.rumor
    setf legend_rumor
@end
@script find_bench interact
    jf frag_4 empty
    say d1.bench.look
    give_item origin_shard 1
    jv 0 0 full
    setf frag_4
    sfx item
    say gl.d1.got
    end
  full:
    say gl.found.full
    end
  empty:
    say d1.bench.empty
@end
